// The bundled starter kit (samples/starter/, generated by
// scripts/make-starter-kit.mjs) as a read-only library: "Use starter kit" in
// the Browser. Vite resolves these URLs from the repo (in dev through
// /@fs/, allowed by server.fs.allow; in a build the files are emitted as
// assets), and the library reads them with fetch(). Nothing can be written
// there, so Save patch is disabled while it is the library.
const urls = import.meta.glob('../../../samples/starter/*.{wav,aif,aiff,mp3,flac,ogg,m4a}', {
  query: '?url',
  import: 'default',
  eager: true,
}) as Record<string, string>;

export interface StarterKit {
  name: string;
  /** Root-level file names and the URL each is fetched from. */
  files: { path: string; url: string }[];
}

export const STARTER_KIT: StarterKit = {
  name: 'Starter kit',
  files: Object.entries(urls).map(([k, url]) => ({ path: k.slice(k.lastIndexOf('/') + 1), url })),
};

export async function fetchBytes(url: string): Promise<ArrayBuffer> {
  const r = await fetch(url);
  if (!r.ok) throw new Error(`HTTP ${r.status}`);
  return r.arrayBuffer();
}
